public void priorityInsert(Patient p) {
    Queue<Patient> temp = new Queue<Patient>();
    boolean done = false;
    while (!q.isEmpty()) {
        Patient x = q.remove();
        // p נכנס לפני החולה הראשון שרמת הדחיפות שלו נמוכה משלו (אחרי כל מי שבאותה רמה)
        if (!done && x.getPriority() < p.getPriority()) {
            temp.insert(p);
            done = true;
        }
        temp.insert(x);
    }
    if (!done) {
        temp.insert(p);
    }
    while (!temp.isEmpty()) {
        q.insert(temp.remove());
    }
}

public void update(int id, int pri) {
    Queue<Patient> temp = new Queue<Patient>();
    Patient found = null;
    // מוציאים את החולה מהתור; שאר החולים נשארים באותו הסדר
    while (!q.isEmpty()) {
        Patient x = q.remove();
        if (x.getId() == id) {
            found = x;
        } else {
            temp.insert(x);
        }
    }
    while (!temp.isEmpty()) {
        q.insert(temp.remove());
    }
    found.setPriority(pri);
    priorityInsert(found);
}

