public static PriorQueue make(int[] ids, int[] pris) {
    PriorQueue pq = new PriorQueue();
    for (int i = 0; i < ids.length; i++) {
        pq.getQ().insert(new Patient(ids[i], pris[i]));
    }
    return pq;
}

